import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int wins = 0;

        for (int i = 0; i < 6; i++) {
            String result = sc.nextLine().trim();
            if (result.equals("V")) {
                wins++;
            }
        }

        if (wins >= 5) {
            System.out.println(1);
        } else if (wins >= 3) {
            System.out.println(2);
        } else if (wins >= 1) {
            System.out.println(3);
        } else {
            System.out.println(-1);
        }
    }
}
